eturn_status, r.refund_status, r.is_refunded, r.forward_tracking_number, r.return_tracking_number, null as product_id FROM orders o LEFT JOIN returns r ON o.seller_order_id = r.seller_order_id AND o.sku_id = r.sku_id;",
